<?php
namespace App\Services; use InvalidArgumentException;
class DomainNormalizer { public function normalize(string $input):string { $input=trim(strtolower($input)); $candidate=str_contains($input,'://')?$input:'https://'.$input; $host=parse_url($candidate,PHP_URL_HOST); if(!$host)$host=parse_url($candidate,PHP_URL_PATH); $host=rtrim((string)$host,'.'); if($host==='::1'||filter_var($host,FILTER_VALIDATE_IP))return $host; if(!filter_var($host,FILTER_VALIDATE_DOMAIN,FILTER_FLAG_HOSTNAME))throw new InvalidArgumentException('Invalid domain.'); return $host; } public function canonical(string $host):string{return str_starts_with($host,'www.')?substr($host,4):$host;} public function isNonProduction(string $host):bool{return in_array($host,['localhost','127.0.0.1','::1'],true)||str_ends_with($host,'.test')||str_ends_with($host,'.local');} }
